// One-off: rename PillComponent input disableTooltip -> hideHint in the places
// ng-facts rename-input does not cover (subclass bindings, template-ref reads,
// typed TS reads, setInput strings). Usage: node rename-rest.mjs [--write]
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import * as ng from "@angular/compiler";
import ts from "typescript";

const OLD = "disableTooltip";
const NEW = "hideHint";
const PILL_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);
const WRITE = process.argv.includes("--write");
const root = process.cwd();

const edits = new Map(); // file -> [{start,end}]
const notes = [];
function addEdit(file, start, end) {
    const list = edits.get(file) ?? [];
    list.push({ start, end });
    edits.set(file, list);
}

// ---------- TypeScript program ----------
const cfgPath = path.join(root, "tsconfig.json");
const cfg = ts.readConfigFile(cfgPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(cfg.config, ts.sys, root);
const program = ts.createProgram(parsed.fileNames, parsed.options);
const checker = program.getTypeChecker();

function declaredInPill(sym) {
    if (!sym) return false;
    const decls = sym.getDeclarations() ?? [];
    return decls.some(d => {
        const cls = d.parent;
        return ts.isClassDeclaration(cls) && cls.name?.text === "PillComponent"
            && cls.getSourceFile().fileName.endsWith("lib/pill.component.ts");
    });
}

// ---------- template handling ----------
class ExprVisitor extends ng.RecursiveAstVisitor {
    constructor(refs, report) { super(); this.refs = refs; this.report = report; }
    visitPropertyRead(ast, ctx) {
        if (ast.name === OLD) {
            const r = ast.receiver;
            if (r instanceof ng.PropertyRead && r.receiver instanceof ng.ImplicitReceiver) {
                const tag = this.refs.get(r.name);
                if (tag === undefined) this.report(`unresolved receiver '${r.name}'`, ast.nameSpan.start);
                else if (PILL_TAGS.has(tag)) this.report(null, ast.nameSpan.start, ast.nameSpan.end);
                else this.report(`skip: receiver '${r.name}' is <${tag}>`, ast.nameSpan.start);
            } else if (r instanceof ng.ImplicitReceiver) {
                // bare `disableTooltip` in a template: the host class field, leave alone
            } else {
                this.report(`unresolved complex receiver`, ast.nameSpan.start);
            }
        }
        super.visitPropertyRead(ast, ctx);
    }
}

function processTemplate(text, fileLabel, toFileOffset, file) {
    const parsedT = ng.parseTemplate(text, fileLabel, { preserveWhitespaces: true, leadingTriviaChars: [] });
    if (parsedT.errors?.length) { notes.push(`${fileLabel}: parse errors ${parsedT.errors.map(e => e.msg).join("; ")}`); }
    const refs = new Map();
    const exprs = [];
    const report = (msg, start, end) => {
        if (msg) notes.push(`${fileLabel}@${start}: ${msg}`);
        else addEdit(file, toFileOffset(start), toFileOffset(end));
    };
    const pushExpr = (e) => { if (e) exprs.push(e instanceof ng.ASTWithSource ? e.ast : e); };
    class V extends ng.TmplAstRecursiveVisitor {
        visitElement(el) {
            for (const r of el.references) if (!r.value) refs.set(r.name, el.name);
            if (PILL_TAGS.has(el.name)) {
                for (const a of el.attributes) if (a.name === OLD) addEdit(file, toFileOffset(a.keySpan.start.offset), toFileOffset(a.keySpan.end.offset));
                for (const i of el.inputs) if (i.name === OLD) addEdit(file, toFileOffset(i.keySpan.start.offset), toFileOffset(i.keySpan.end.offset));
            } else {
                for (const a of el.attributes) if (a.name === OLD && el.name !== "app-card" && el.name !== "app-pill-legacy") notes.push(`${fileLabel}: attr on <${el.name}> left alone`);
                for (const i of el.inputs) if (i.name === OLD && el.name !== "app-card" && el.name !== "app-pill-legacy") notes.push(`${fileLabel}: input on <${el.name}> left alone`);
            }
            for (const i of el.inputs) pushExpr(i.value);
            for (const o of el.outputs) pushExpr(o.handler);
            super.visitElement(el);
        }
        visitTemplate(t) {
            for (const r of t.references) if (!r.value) refs.set(r.name, t.tagName ?? "ng-template");
            for (const i of t.inputs) pushExpr(i.value);
            for (const i of t.templateAttrs) if (i instanceof ng.TmplAstBoundAttribute) pushExpr(i.value);
            super.visitTemplate(t);
        }
        visitBoundText(t) { pushExpr(t.value); }
        visitIfBlockBranch(b) { pushExpr(b.expression); super.visitIfBlockBranch(b); }
        visitForLoopBlock(b) { pushExpr(b.expression); pushExpr(b.trackBy); super.visitForLoopBlock(b); }
        visitSwitchBlock(b) { pushExpr(b.expression); super.visitSwitchBlock(b); }
        visitSwitchBlockCase(b) { pushExpr(b.expression); super.visitSwitchBlockCase(b); }
        visitLetDeclaration(d) { pushExpr(d.value); }
        visitComponent(c) { for (const i of c.inputs) pushExpr(i.value); super.visitComponent(c); }
        visitDirective(d) { for (const i of d.inputs) pushExpr(i.value); super.visitDirective(d); }
    }
    ng.tmplAstVisitAll(new V(), parsedT.nodes);
    const ev = new ExprVisitor(refs, report);
    for (const e of exprs) e.visit(ev, null);
}

for (const sf of program.getSourceFiles()) {
    if (sf.isDeclarationFile || !path.resolve(sf.fileName).startsWith(path.join(root, "src"))) continue;
    const file = path.resolve(sf.fileName);
    const visit = (node) => {
        // @Component({ template / templateUrl })
        if (ts.isPropertyAssignment(node) && ts.isIdentifier(node.name)) {
            if (node.name.text === "template" && ts.isNoSubstitutionTemplateLiteral(node.initializer)) {
                const lit = node.initializer;
                const raw = sf.text.slice(lit.getStart(sf) + 1, lit.getEnd() - 1);
                if (raw !== lit.text) notes.push(`${sf.fileName}: inline template has escapes, skipped`);
                else processTemplate(raw, sf.fileName + "#template", (o) => lit.getStart(sf) + 1 + o, file);
            } else if (node.name.text === "template" && ts.isStringLiteral(node.initializer)) {
                notes.push(`${sf.fileName}: string-literal template, skipped`);
            } else if (node.name.text === "templateUrl" && ts.isStringLiteral(node.initializer)) {
                const tf = path.resolve(path.dirname(file), node.initializer.text);
                const text = readFileSync(tf, "utf8");
                processTemplate(text, tf, (o) => o, tf);
            }
        }
        // x.disableTooltip where the property is declared on PillComponent
        if (ts.isPropertyAccessExpression(node) && node.name.text === OLD) {
            const sym = checker.getSymbolAtLocation(node.name);
            if (declaredInPill(sym)) addEdit(file, node.name.getStart(sf), node.name.getEnd());
            else notes.push(`${sf.fileName}:${sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1}: TS read left alone (${sym ? "other owner" : "no symbol"})`);
        }
        // ref.setInput("disableTooltip", ...)
        if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression) && node.expression.name.text === "setInput"
            && node.arguments.length && ts.isStringLiteralLike(node.arguments[0]) && node.arguments[0].text === OLD) {
            const t = checker.getTypeAtLocation(node.expression.expression);
            const args = checker.getTypeArguments(t);
            const prop = args[0]?.getProperty(OLD);
            const line = sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
            if (declaredInPill(prop)) addEdit(file, node.arguments[0].getStart(sf) + 1, node.arguments[0].getEnd() - 1);
            else notes.push(`${sf.fileName}:${line}: setInput left alone (${checker.typeToString(t)})`);
        }
        ts.forEachChild(node, visit);
    };
    visit(sf);
}

let total = 0;
for (const [file, list] of edits) {
    const uniq = [...new Map(list.map(e => [e.start, e])).values()].sort((a, b) => b.start - a.start);
    let text = readFileSync(file, "utf8");
    for (const e of uniq) {
        if (text.slice(e.start, e.end) !== OLD) { notes.push(`${file}@${e.start}: expected '${OLD}', got '${text.slice(e.start, e.end)}' — skipped`); continue; }
        text = text.slice(0, e.start) + NEW + text.slice(e.end);
        total++;
    }
    if (WRITE) writeFileSync(file, text);
}
console.log(`${total} edits in ${edits.size} files${WRITE ? " — written" : " — dry run"}`);
for (const n of notes) console.log("  " + n);

